Definition lit_lazy_holds (m : amap) (slo shi : Z) : bool :=
  (negb (is_fog m) && mkind_eqb (am_kind m) KRWLAZY &&
   match am_base m, am_len m with
   | ELit B, ELit L => (Z.leb 0 B && Z.ltb 0 L && Z.ltb (B + L) two64 && Z.leb B slo && Z.leb shi (B + L))%bool
   | _, _ => false
   end)%bool.
Definition shadow_band (k : list kentry) (ms : list amap) (b n : expr) (sb : expr) (sk : Z) (sn : expr) : bool :=
  flat_x k sb sk sn &&
  match xlo k b, xhi k b, xhi k n with
  | Some blo, Some bhi, Some nhi =>
      existsb (fun K => match K with
        | KDisj (SA (ELit lo) 0) (ELit L) (SA b' 0) n' =>
            (expr_eqb b' b && expr_eqb n' n && Z.leb 0 lo && Z.leb 0 L && Z.ltb (lo + L) two64
             && existsb (fun m => lit_lazy_holds m (shadow_off A + blo / 8) (shadow_off A + lo / 8)) ms
             && existsb (fun m => lit_lazy_holds m (shadow_off A + (lo + L) / 8) (shadow_off A + (bhi + nhi) / 8)) ms)%bool
        | _ => false end) k
  | _, _, _ => false
  end%bool.
Definition shadow_bandB (bc : bctx) (ms : list amap) (b n : expr) (sb : expr) (sk : Z) (sn : expr) : bool :=
  flat_xB bc sb sk sn &&
  match xloB bc b, xhiB bc b, xhiB bc n with
  | Some blo, Some bhi, Some nhi =>
      existsb (fun K => match K with
        | KDisj (SA (ELit lo) 0) (ELit L) (SA b' 0) n' =>
            (expr_eqb b' b && expr_eqb n' n && Z.leb 0 lo && Z.leb 0 L && Z.ltb (lo + L) two64
             && existsb (fun m => lit_lazy_holds m (shadow_off A + blo / 8) (shadow_off A + lo / 8)) ms
             && existsb (fun m => lit_lazy_holds m (shadow_off A + (lo + L) / 8) (shadow_off A + (bhi + nhi) / 8)) ms)%bool
        | _ => false end) (bc_fk bc)
  | _, _, _ => false
  end%bool.
