Fixpoint kfind_litword (k : list kentry) (b : expr) (off : Z) (n : nat) : option Z :=
  match k with
  | [] => None
  | KWord (SA b' off') n' (ELit c) :: r =>
      if (expr_eqb b' b && Z.eqb off' off && Nat.eqb n' n)%bool then Some c else kfind_litword r b off n
  | _ :: r => kfind_litword r b off n
  end.

Definition node_absword (cs : acs) (b : expr) (off : Z) (n : nat) (lo hi : Z) : option acs :=
  if (fresh_ok cs && Nat.leb 1 n && Nat.leb n 8)%bool then
    match kfind_litword (kn cs) b off n with
    | Some c =>
        if (Z.leb lo c && Z.leb c hi && Z.leb 0 lo && Z.ltb hi two64)%bool then
          let v := nxt cs in let ss := a_ss cs in
          let k0 := if expr_eqb b (ELit 0) then kimg_cut (kn cs) off (Z.of_nat n) else kn cs in
          let k' := KWord (SA b off) n (EVar v) :: KRange (EVar v) lo hi :: kn_havoc k0 b off (ELit (Z.of_nat n)) in
          Some (with_ss cs (mk_ss (s_pc ss) (s_regs ss) k' (S v)))
        else None
    | None => None
    end
  else None.

