Definition hop_sub (b n eb en : expr) (h : hop) : hop :=
  let g y := if expr_eqb y n then en else y in
  match h with
  | HCons x y => if expr_eqb x b then HCons eb (g y) else h
  | HSub x y => if expr_eqb x b then HSub eb (g y) else h
  end.
Definition node_habs (cs : acs) (i : nat) (lo hi nlo nhi : Z) : option acs :=
  match nth_error (a_hlz cs) i with
  | Some ev =>
      let b := hop_b ev in let n := hop_n ev in let k := kn cs in
      match xlo k b, xhi k b, xhi k (eadd b n), xlo k n, xhi k n with
      | Some blo, Some bhi, Some ehi, Some nl, Some nh =>
          if (fresh_ok cs && Z.leb lo blo && Z.leb bhi hi && Z.leb ehi hi && Z.leb nlo nl && Z.leb nh nhi && Z.leb 0 lo && Z.ltb hi two64 && Z.leb 0 nlo)%bool then
            let v := nxt cs in let eb := EVar v in let en := EVar (S v) in
            let facts := [KRange eb lo hi; KRange en nlo nhi; KRange (eadd eb en) 0 hi]
                         ++ (if Z.leb 12 (ealign k b) then [KAlign eb 4096] else [])
                         ++ (if Z.leb 12 (ealign k n) then [KAlign en 4096] else []) in
            let ss := a_ss cs in
            Some (ACS (mk_ss (s_pc ss) (s_regs ss) (facts ++ s_know ss) (S (S v)))
                      (a_maps cs) (a_totsz cs) (a_ylo cs) (a_eager cs) (a_vis cs) (a_ghost cs) (a_abytes cs) (a_brk cs) (a_fd cs) (a_tidset cs)
                      (map (hop_sub b n eb en) (a_hna cs)) (map (hop_sub b n eb en) (a_hlz cs)))
          else None
      | _, _, _, _, _ => None
      end
  | None => None
  end.

